import { chromium } from 'playwright'

const exe = process.env.PLAYWRIGHT_CHROMIUM_EXECUTABLE
const browser = await chromium.launch({ executablePath: exe, args: ['--no-sandbox'] })
const ctx = await browser.newContext({ viewport: { width: 390, height: 844 }, deviceScaleFactor: 2 })
const page = await ctx.newPage()
page.on('console', m => console.log('[console]', m.type(), m.text().slice(0,200)))

async function dump(url, label) {
  await page.goto(url, { waitUntil: 'domcontentloaded', timeout: 30000 })
  await page.waitForTimeout(1500)
  const info = await page.evaluate(() => {
    const btns = [...document.querySelectorAll('button,[role=button]')].map(b => (b.textContent||'').trim()).filter(Boolean).slice(0,30)
    const links = [...document.querySelectorAll('a')].map(a => ({t:(a.textContent||'').trim().slice(0,40), h:a.getAttribute('href')})).slice(0,30)
    return { title: document.title, url: location.href, btns, links, bodyText: (document.body.innerText||'').slice(0,600) }
  })
  console.log('=====', label, url, '=====')
  console.log(JSON.stringify(info, null, 2))
}

await dump('http://localhost:8443/', 'REF-root')
await browser.close()

