import { chromium } from 'playwright'

const exe = process.env.PLAYWRIGHT_CHROMIUM_EXECUTABLE
const browser = await chromium.launch({ executablePath: exe, args: ['--no-sandbox'] })
const ctx = await browser.newContext({ viewport: { width: 390, height: 844 }, deviceScaleFactor: 2 })
const page = await ctx.newPage()

async function snap(label) {
  await page.waitForTimeout(1200)
  const info = await page.evaluate(() => {
    const btns = [...document.querySelectorAll('button,[role=button]')].map(b => (b.textContent||'').trim()).filter(Boolean).slice(0,40)
    return { url: location.href, btns, bodyText: (document.body.innerText||'').slice(0,700) }
  })
  console.log('=====', label, '=====')
  console.log(JSON.stringify(info, null, 2))
}

await page.goto('http://localhost:8443/', { waitUntil: 'domcontentloaded', timeout: 30000 })
await page.waitForTimeout(1500)
// check agreement checkbox (a checkbox input or clickable)
const cb = page.locator('input[type=checkbox]').first()
if (await cb.count()) { await cb.check({ timeout: 3000 }).catch(async()=>{ await cb.click({force:true}) }) }
else {
  // try clicking text 同意
  await page.getByText('同意', { exact: false }).first().click({ timeout: 3000 }).catch(e => console.log('no agree click', e.message))
}
await page.getByRole('button', { name: '登录', exact: true }).click({ timeout: 5000 }).catch(e => console.log('login err', e.message))
await snap('after 登录 + agree')

await browser.close()

import { chromium } from 'playwright'

const exe = process.env.PLAYWRIGHT_CHROMIUM_EXECUTABLE
const browser = await chromium.launch({ executablePath: exe, args: ['--no-sandbox'] })
const ctx = await browser.newContext({ viewport: { width: 390, height: 844 }, deviceScaleFactor: 2 })
const page = await ctx.newPage()

async function snap(label) {
  await page.waitForTimeout(1200)
  const info = await page.evaluate(() => {
    const btns = [...document.querySelectorAll('button,[role=button]')].map(b => (b.textContent||'').trim()).filter(Boolean).slice(0,40)
    return { url: location.href, btns, bodyText: (document.body.innerText||'').slice(0,800) }
  })
  console.log('=====', label, '=====')
  console.log(JSON.stringify(info, null, 2))
}

await page.goto('http://localhost:8443/', { waitUntil: 'domcontentloaded', timeout: 30000 })
await page.waitForTimeout(1200)
await page.locator('input[type=checkbox]').first().check({ timeout: 3000 }).catch(()=>{})
await page.getByRole('button', { name: '登录', exact: true }).click({ timeout: 5000 }).catch(()=>{})
await page.waitForTimeout(1200)
await page.getByText('物业手持端', { exact: false }).first().click({ timeout: 5000 }).catch(e => console.log('enter err', e.message))
await snap('workbench (物业手持端)')

// list sidebar tab text
const side = await page.evaluate(() => [...document.querySelectorAll('*')].filter(e=>/综合查询|项目检查|防台防汛/.test(e.textContent||'') && e.children.length<2).map(e=>(e.textContent||'').trim()).slice(0,10))
console.log('SIDE CANDIDATES', JSON.stringify(side))

await browser.close()

import { chromium } from 'playwright'

const exe = process.env.PLAYWRIGHT_CHROMIUM_EXECUTABLE
const browser = await chromium.launch({ executablePath: exe, args: ['--no-sandbox'] })
const ctx = await browser.newContext({ viewport: { width: 390, height: 844 }, deviceScaleFactor: 2 })
const page = await ctx.newPage()

async function snap(label) {
  await page.waitForTimeout(1000)
  const info = await page.evaluate(() => {
    return { url: location.href, bodyText: (document.body.innerText||'').slice(0,600) }
  })
  console.log('=====', label, '=====')
  console.log(JSON.stringify(info, null, 2))
}

await page.goto('http://localhost:8443/', { waitUntil: 'domcontentloaded', timeout: 30000 })
await page.waitForTimeout(1200)
await page.locator('input[type=checkbox]').first().check({ timeout: 3000 }).catch(()=>{})
await page.getByRole('button', { name: '登录', exact: true }).click({ timeout: 5000 }).catch(()=>{})
await page.waitForTimeout(1200)
await page.getByText('物业手持端', { exact: false }).first().click({ timeout: 5000 }).catch(()=>{})
await page.waitForTimeout(1000)

// click bottom nav 工作台
const navs = ['工作台', '住房服务', '数智', '个人中心', '首页']
for (const n of navs) {
  // click the bottom-nav item whose text exactly n and inside a nav-ish container
  const clicked = await page.evaluate((label) => {
    const els = [...document.querySelectorAll('button,[role=button],[role=tab],a,div,span')]
    // find elements with textContent exactly label, prefer deepest
    const cands = els.filter(e => (e.textContent||'').trim() === label)
    if (!cands.length) return false
    const el = cands[cands.length - 1]
    el.click()
    return true
  }, n)
  if (!clicked) { console.log('not found nav', n); continue }
  await snap('nav:' + n)
}

await browser.close()

