import { chromium } from 'playwright'
import fs from 'fs'

const exe = process.env.PLAYWRIGHT_CHROMIUM_EXECUTABLE
const OUT = 'artifacts'
fs.mkdirSync(OUT, { recursive: true })

const browser = await chromium.launch({ executablePath: exe, args: ['--no-sandbox'] })

function newPage() {
  return browser.newContext({ viewport: { width: 390, height: 844 }, deviceScaleFactor: 2 }).then(c => c.newPage())
}

// measure: return header rect and first content element below header
async function measure(page, label) {
  return await page.evaluate((label) => {
    function rect(el){ const r = el.getBoundingClientRect(); return {x:r.x,y:r.y,w:r.width,h:r.height,b:r.bottom} }
    // find fixed/sticky header-like element (top area, has short height)
    const all = [...document.querySelectorAll('body *')]
    // header candidates: elements whose text matches known titles AND near top, or element with position fixed at top
    let header = null
    for (const el of all) {
      const cs = getComputedStyle(el)
      const r = el.getBoundingClientRect()
      if ((cs.position === 'fixed' || cs.position === 'sticky') && r.top >= 0 && r.top < 120 && r.height > 40 && r.height < 130 && r.width > 200) {
        // likely app-header/top bar
        header = { tag: el.tagName, cls: el.className, ...rect(el) }
        break
      }
    }
    // find first main content element: first child of the scroll/content container after header
    // Heuristic: the topmost element with a background/surface that starts below header and has meaningful height, OR first block child
    const vh = window.innerHeight
    // Collect top-level "blocks": elements whose y >= headerBottom-2 and height>20 and width>150, not fixed, not containing header
    const headerBottom = header ? header.b : 0
    let first = null
    for (const el of all) {
      const cs = getComputedStyle(el)
      if (cs.position === 'fixed') continue
      const r = el.getBoundingClientRect()
      if (r.width < 150 || r.height < 16) continue
      if (r.top < headerBottom - 2) continue
      // must be a leaf-ish content block: has some text or is a card
      const txt = (el.textContent||'').trim()
      // require this element visually starts earliest; skip elements that merely wrap the whole page (height near vh and top 0)
      if (r.top >= headerBottom - 2 && r.top < vh) {
        if (!first || r.top < first.y - 0.5) {
          first = { tag: el.tagName, cls: (el.className||'').toString().slice(0,80), y: r.top, h: r.height, txt: txt.slice(0,40) }
        }
      }
    }
    return { label, headerBottom: headerBottom, header, first }
  }, label)
}

async function shot(page, file) {
  await page.screenshot({ path: file, animations: 'disabled', timeout: 60000 })
}

// block remote fonts to avoid hang
async function blockFonts(page) {
  await page.route('**/*', route => {
    const u = route.request().url()
    if (/\.(woff2?|ttf|otf)(\?|$)/i.test(u) || /static\.figma\.com\/font/i.test(u)) return route.abort()
    route.continue()
  })
}

const results = []

// ====== REF site ======
{
  const page = await newPage()
  await blockFonts(page)
  const base = 'http://localhost:8443/'
  await page.goto(base, { waitUntil: 'domcontentloaded', timeout: 30000 })
  await page.waitForTimeout(1500)
  await page.locator('input[type=checkbox]').first().check({ timeout: 3000 }).catch(()=>{})
  await page.getByRole('button', { name: '登录', exact: true }).click({ timeout: 5000 }).catch(()=>{})
  await page.waitForTimeout(1200)
  // systems page screenshot
  await shot(page, `${OUT}/ref-systems.png`)
  results.push({ site:'ref', page:'systems', ...(await measure(page,'systems')) })
  // enter 物业手持端 -> home
  await page.getByText('物业手持端', { exact: false }).first().click({ timeout: 5000 }).catch(()=>{})
  await page.waitForTimeout(1200)
  await shot(page, `${OUT}/ref-home.png`)
  results.push({ site:'ref', page:'home', ...(await measure(page,'home')) })

  async function clickNav(n){
    await page.evaluate((label)=>{ const els=[...document.querySelectorAll('button,[role=button],div,span,a')]; const c=els.filter(e=>(e.textContent||'').trim()===label); if(c.length) c[c.length-1].click(); }, n)
    await page.waitForTimeout(1200)
  }
  await clickNav('工作台')
  await shot(page, `${OUT}/ref-workbench.png`)
  results.push({ site:'ref', page:'workbench', ...(await measure(page,'workbench')) })
  // ref workbench side tabs
  for (const st of ['综合查询','项目检查','防台防汛']) {
    const ok = await page.evaluate((label)=>{ const els=[...document.querySelectorAll('*')]; const c=els.filter(e=>(e.textContent||'').trim()===label && e.children.length<=1); if(c.length){c[0].click();return true} return false }, st)
    if (ok) { await page.waitForTimeout(800); await shot(page, `${OUT}/ref-workbench-${st}.png`); results.push({ site:'ref', page:'workbench-'+st, ...(await measure(page,'workbench-'+st)) }) }
  }
  await clickNav('住房服务')
  await shot(page, `${OUT}/ref-housing.png`)
  results.push({ site:'ref', page:'housing', ...(await measure(page,'housing')) })
  await clickNav('数智')
  await shot(page, `${OUT}/ref-data.png`)
  results.push({ site:'ref', page:'data', ...(await measure(page,'data')) })
  await page.context().close()
}

// ====== MINE site ======
{
  const page = await newPage()
  await blockFonts(page)
  const base = 'http://127.0.0.1:8095/'
  // hash routes
  const routes = [
    ['systems','#/pages/systems/index'],
    ['home','#/pages/home/index'],
    ['workbench','#/pages/workbench/index'],
    ['housing','#/pages/housing/index'],
    ['data','#/pages/data/index'],
  ]
  for (const [name, hash] of routes) {
    await page.goto(base + hash, { waitUntil: 'domcontentloaded', timeout: 30000 })
    await page.waitForTimeout(1500)
    await shot(page, `${OUT}/mine-${name}.png`)
    results.push({ site:'mine', page:name, ...(await measure(page,name)) })
  }
  // workbench side tabs
  for (const st of ['综合查询','项目检查','防台防汛']) {
    const ok = await page.evaluate((label)=>{ const els=[...document.querySelectorAll('*')]; const c=els.filter(e=>(e.textContent||'').trim()===label && e.children.length<=1); if(c.length){c[0].click();return true} return false }, st)
    if (ok) { await page.waitForTimeout(700); await shot(page, `${OUT}/mine-workbench-${st}.png`); results.push({ site:'mine', page:'workbench-'+st, ...(await measure(page,'workbench-'+st)) }) }
  }
  await page.context().close()
}

fs.writeFileSync(`${OUT}/measure.json`, JSON.stringify(results, null, 2))
console.log('=== MEASURE RESULTS ===')
for (const r of results) {
  console.log(`${r.site.padEnd(5)} ${String(r.page).padEnd(22)} headerBottom=${r.headerBottom} firstY=${r.first?.y} firstH=${r.first?.h} cls=${r.first?.cls} txt="${r.first?.txt}"`)
}
await browser.close()

import { chromium } from 'playwright'
import fs from 'fs'
const exe = process.env.PLAYWRIGHT_CHROMIUM_EXECUTABLE
const browser = await chromium.launch({ executablePath: exe, args: ['--no-sandbox'] })
function newPage(){ return browser.newContext({ viewport:{width:390,height:844}, deviceScaleFactor:2 }).then(c=>c.newPage()) }
async function blockFonts(page){ await page.route('**/*', r=>{ const u=r.request().url(); if(/\.(woff2?|ttf|otf)(\?|$)/i.test(u)||/static\.figma\.com\/font/i.test(u)) return r.abort(); r.continue() }) }

// Generic precise measurement:
//  headerTitle: text node bounding of page title (首页/工作台/...) OR fixed header box
//  headerBox: fixed top bar rect
//  firstCard: first element that has a box-shadow or background card look, or known card class, below header
async function precise(page){
  return await page.evaluate(()=>{
    const rect = el => { const r=el.getBoundingClientRect(); return {x:+r.x.toFixed(1),y:+r.y.toFixed(1),w:+r.width.toFixed(1),h:+r.height.toFixed(1),b:+r.bottom.toFixed(1)} }
    const all=[...document.querySelectorAll('body *')]
    // fixed header
    let headerBox=null
    for(const el of all){ const cs=getComputedStyle(el); const r=el.getBoundingClientRect(); if(cs.position==='fixed'&&r.top<120&&r.height>30&&r.height<130&&r.width>200){ headerBox={cls:(el.className||'').toString(),...rect(el)}; break } }
    const hb = headerBox? headerBox.b : 0
    // scroll container / content wrapper: element that has overflow auto/scroll and height near viewport
    let contentWrap=null
    for(const el of all){ const cs=getComputedStyle(el); const r=el.getBoundingClientRect(); if((cs.overflowY==='auto'||cs.overflowY==='scroll')&&r.height>300&&r.width>200){ contentWrap={cls:(el.className||'').toString().slice(0,60),...rect(el)}; break } }
    const ctop = contentWrap? contentWrap.y : 0
    // first card: element with box-shadow != none, height>30, width>150, top>=hb-4
    let firstCard=null
    for(const el of all){ const cs=getComputedStyle(el); if(cs.position==='fixed') continue; const r=el.getBoundingClientRect(); if(r.width<150||r.height<28) continue; if(r.top<hb-4) continue; const shadow=cs.boxShadow&&cs.boxShadow!=='none'; const bg=cs.backgroundColor; const hasBg = bg && bg!=='rgba(0, 0, 0, 0)' && bg!=='transparent'; if(shadow||hasBg){ if(!firstCard||r.top<firstCard.y-0.5){ firstCard={cls:(el.className||'').toString().slice(0,60),shadow,bg,...rect(el)} } } }
    // first any content block
    let firstBlock=null
    for(const el of all){ const cs=getComputedStyle(el); if(cs.position==='fixed') continue; const r=el.getBoundingClientRect(); if(r.width<150||r.height<16) continue; if(r.top<hb-4) continue; const txt=(el.textContent||'').trim(); if(!txt && !(cs.boxShadow&&cs.boxShadow!=='none')) continue; if(!firstBlock||r.top<firstBlock.y-0.5){ firstBlock={cls:(el.className||'').toString().slice(0,60),txt:txt.slice(0,30),...rect(el)} } }
    return { vh: window.innerHeight, headerBox, contentWrap, contentTop:ctop, firstCard, firstBlock,
      gapCard: firstCard && headerBox ? +(firstCard.y-headerBox.b).toFixed(1) : null,
      gapBlock: firstBlock && headerBox ? +(firstBlock.y-headerBox.b).toFixed(1) : null }
  })
}

const out=[]
// REF
{
  const page=await newPage(); await blockFonts(page)
  await page.goto('http://localhost:8443/',{waitUntil:'domcontentloaded',timeout:30000}); await page.waitForTimeout(1500)
  await page.locator('input[type=checkbox]').first().check({timeout:3000}).catch(()=>{})
  await page.getByRole('button',{name:'登录',exact:true}).click({timeout:5000}).catch(()=>{}); await page.waitForTimeout(1200)
  out.push({site:'ref',page:'systems',...(await precise(page))})
  await page.getByText('物业手持端',{exact:false}).first().click({timeout:5000}).catch(()=>{}); await page.waitForTimeout(1200)
  out.push({site:'ref',page:'home',...(await precise(page))})
  const clickNav=async n=>{ await page.evaluate(l=>{const e=[...document.querySelectorAll('button,[role=button],div,span,a')].filter(x=>(x.textContent||'').trim()===l); if(e.length)e[e.length-1].click()},n); await page.waitForTimeout(1000) }
  await clickNav('工作台'); out.push({site:'ref',page:'workbench',...(await precise(page))})
  await clickNav('住房服务'); out.push({site:'ref',page:'housing',...(await precise(page))})
  await clickNav('数智'); out.push({site:'ref',page:'data',...(await precise(page))})
  await page.context().close()
}
// MINE
{
  const page=await newPage(); await blockFonts(page)
  for(const [name,hash] of [['systems','#/pages/systems/index'],['home','#/pages/home/index'],['workbench','#/pages/workbench/index'],['housing','#/pages/housing/index'],['data','#/pages/data/index']]){
    await page.goto('http://127.0.0.1:8095/'+hash,{waitUntil:'domcontentloaded',timeout:30000}); await page.waitForTimeout(1400)
    out.push({site:'mine',page:name,...(await precise(page))})
  }
  await page.context().close()
}
fs.writeFileSync('artifacts/precise.json',JSON.stringify(out,null,2))
for(const r of out){
  console.log(`${r.site.padEnd(4)} ${r.page.padEnd(10)} hdrB=${r.headerBox?.b} | firstCard.y=${r.firstCard?.y} gapCard=${r.gapCard} cls=${r.firstCard?.cls} | firstBlock.y=${r.firstBlock?.y} gapBlock=${r.gapBlock}`)
}
await browser.close()

