import { chromium } from 'playwright'
const exe = process.env.PLAYWRIGHT_CHROMIUM_EXECUTABLE
const browser = await chromium.launch({ executablePath: exe, args: ['--no-sandbox'] })
function newPage(){ return browser.newContext({ viewport:{width:390,height:844}, deviceScaleFactor:2 }).then(c=>c.newPage()) }
async function blockFonts(page){ await page.route('**/*', r=>{ const u=r.request().url(); if(/\.(woff2?|ttf|otf)(\?|$)/i.test(u)||/static\.figma\.com\/font/i.test(u)) return r.abort(); r.continue() }) }
async function wrap(page,label){
  return await page.evaluate((label)=>{
    const rect=el=>{const r=el.getBoundingClientRect();return {y:+r.y.toFixed(1),h:+r.height.toFixed(1)}}
    const all=[...document.querySelectorAll('body *')]
    // find the content wrapper: element whose className contains content/workspace that is descendant area
    const cand=all.filter(e=>{const c=(e.className||'').toString();return /content|workspace|hero|grid|main|region|metric/.test(c)})
    // find topmost (y smallest) significant block below header(56) that has height>20 width>300
    let first=null
    for(const el of all){const cs=getComputedStyle(el); if(cs.position==='fixed')continue; const r=el.getBoundingClientRect(); if(r.top<50||r.width<300||r.height<20)continue; if((el.textContent||'').trim()==='')continue; if(!first||r.top<first.y){first={tag:el.tagName,cls:(el.className||'').toString().slice(0,50),...rect(el),padTop:cs.paddingTop,marTop:cs.marginTop}}}
    // also the wrapper chain from first
    let chain=[]; let el=null
    // locate element
    if(first){ el=all.find(e=>{const r=e.getBoundingClientRect();return Math.abs(r.y-first.y)<0.5 && (e.className||'').toString().slice(0,50)===first.cls}) }
    for(let i=0;i<4&&el;i++){const cs=getComputedStyle(el);chain.push({cls:(el.className||'').toString().slice(0,40),y:+el.getBoundingClientRect().y.toFixed(1),padTop:cs.paddingTop,marTop:cs.marginTop});el=el.parentElement}
    return {label,first,chain}
  },label)
}
{
  const p=await newPage();await blockFonts(p)
  await p.goto('http://localhost:8443/',{waitUntil:'domcontentloaded',timeout:30000});await p.waitForTimeout(1500)
  await p.locator('input[type=checkbox]').first().check({timeout:3000}).catch(()=>{})
  await p.getByRole('button',{name:'登录',exact:true}).click({timeout:5000}).catch(()=>{})
  await p.waitForTimeout(1000); await p.getByText('物业手持端',{exact:false}).first().click({timeout:5000}).catch(()=>{}); await p.waitForTimeout(1200)
  const clickNav=async n=>{ await p.evaluate(l=>{const e=[...document.querySelectorAll('button,[role=button],div,span,a')].filter(x=>(x.textContent||'').trim()===l); if(e.length)e[e.length-1].click()},n); await p.waitForTimeout(1000) }
  console.log('HOME', JSON.stringify(await wrap(p,'home'),null,1))
  await clickNav('住房服务'); console.log('HOUSING', JSON.stringify(await wrap(p,'housing'),null,1))
  await clickNav('工作台'); console.log('WORKBENCH', JSON.stringify(await wrap(p,'workbench'),null,1))
  await clickNav('数智'); console.log('DATA', JSON.stringify(await wrap(p,'data'),null,1))
  await p.context().close()
}
await browser.close()

