+.login-brand-mark{width:64px;height:64px;border-radius:12px;background:rgba(0,79,208,.1);box-shadow:0 1px 2px #0000000d;display:flex;align-items:center;justify-content:center;margin-bottom:16px}
+.login-brand-icon{width:36px;height:36px}
+.login-brand-name{font-size:18px;font-weight:500;line-height:26px;color:var(--c-text)}
+.login-card{width:100%;background:var(--c-surface);border-radius:12px;padding:16px;box-shadow:0 1px 2px #0000000d;display:flex;flex-direction:column;gap:16px}
+.login-field{display:flex;flex-direction:column;gap:8px}
+.login-field-label{font-size:16px;line-height:21px;color:var(--c-text)}
+.login-req{color:#ba1a1a;font-size:12px;font-weight:700;margin-right:2px}
+.login-input-shell{display:flex;align-items:center;gap:10px;height:48px;padding:0 12px;background:#f2f4f8;border-radius:8px;position:relative}
+.login-input-icon{width:20px;height:20px;flex:none}
+.login-input-shell input{flex:1;min-width:0;height:48px;line-height:48px;font-size:14px;color:var(--c-text);background:transparent;border:0}
+.login-eye{width:20px;height:20px;flex:none;opacity:.7}
+.login-eye.active{opacity:1}
+.login-sms-btn{flex:none;font-size:14px;color:#004fd0;line-height:21px}
+.login-sms-btn.disabled{color:#a0a3ad}
+.login-captcha-row{display:flex;align-items:center;gap:8px}
+.login-captcha-row .login-input-shell{flex:1;min-width:0}
+.login-captcha-img{width:76px;height:48px;flex:none;border-radius:8px;background:#f2f4f8;overflow:hidden;display:flex;align-items:center;justify-content:center}
 .login-captcha-image{width:100%;height:100%}
-.login-captcha-placeholder{font-size:13px;color:var(--c-text-3);padding:0 4px;text-align:center}
-.login-error{font-size:15px;line-height:19px;color:#b42318;background:#fff0ee;border-radius:6px;padding:8px 10px}
-.login-submit{height:46px;border-radius:8px;background:var(--c-brand);color:#fff;font-size:18px;font-weight:700;display:flex;align-items:center;justify-content:center;margin-top:2px}
+.login-captcha-ph{font-size:16px;font-weight:700;font-style:italic;letter-spacing:1px;color:#2f6bd8}
+.login-mode-link{align-self:flex-end;font-size:14px;line-height:21px;color:#004fd0}
+.login-error{font-size:14px;line-height:19px;color:#ba1a1a;background:#fdecec;border-radius:6px;padding:8px 10px}
+.login-agreement{display:flex;align-items:center;gap:8px}
+.login-checkbox{width:20px;height:20px;flex:none;border-radius:4px;border:1px solid #c7cbd4;background:#fff;display:flex;align-items:center;justify-content:center}
+.login-checkbox.checked{background:#004fd0;border-color:#004fd0}
+.login-check-glyph{color:#fff;font-size:13px;line-height:1}
+.login-agreement-text{font-size:14px;line-height:20px;color:var(--c-text)}
+.login-submit{height:48px;border-radius:8px;background:#004fd0;color:#fff;font-size:16px;font-weight:500;display:flex;align-items:center;justify-content:center;box-shadow:0 1px 2px #0000000d}
 .login-submit.disabled{opacity:.65}
-.login-foot{font-size:14px;color:var(--c-text-3);line-height:18px;text-align:center;margin-top:24px;padding:0 32px}
 
 /* ===== 业务子系统选择页（复刻截图） ===== */
 .systems-screen{background:#f2f4f8}
-.system-hero{display:flex;flex-direction:column;align-items:center;padding:calc(16px + 72px + var(--status-bar-height,0px)) 16px 16px}
+.system-hero{display:flex;flex-direction:column;align-items:center;padding:12px 16px 16px}
 .system-hero-image{width:min(340px,92vw)}
 .prompt-dot{margin-top:8px;padding:4px 14px;border-radius:99px;background:rgba(230,232,236,.8);display:flex;align-items:center}
 .prompt-dot::before{content:'';display:inline-block;width:6px;height:6px;margin-right:6px;border-radius:50%;background:#004fd0}
