 .article-image{width:80px;height:80px;flex:none;border-radius:8px}
 
 /* ===== 住房服务 ===== */
-.housing-content{display:flex;flex-direction:column}
+.housing-content{display:flex;flex-direction:column;padding-top:28px}
 .housing-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:8px}
 .housing-card{display:flex;min-height:100px;flex-direction:column;align-items:center;justify-content:center;gap:10px;border-radius:12px;background:#fff;box-shadow:var(--shadow-card)}
 .housing-card-title{font-size:14px;font-weight:500;line-height:18px;color:var(--c-text);text-align:center;padding:0 6px}
 
 /* ===== 数智（空占位） ===== */
-.data-empty{display:flex;align-items:center;justify-content:center;min-height:60vh;padding-top:calc(72px + var(--status-bar-height,0px))}
+.data-empty{display:flex;align-items:center;justify-content:center;min-height:40vh;padding:12px 16px}
 .data-empty-text{font-size:15px;color:var(--c-text-3)}
 
